import { useEffect, useMemo, useRef, useState, type MouseEvent } from 'react';
import { ArrowLeft, BookOpen, Check, ChevronDown, ChevronLeft, ChevronRight, CirclePlay, Code2, Eye, EyeOff, FileText, Hash, Heart, Languages, Pause, PenLine, Play, RotateCcw, Search, ShieldCheck, Sparkles, Undo2, Volume2, X } from 'lucide-react';
import raw from './data/generated.json';
import './index.css';

type Mode = 'hanzi'|'words'|'phrases'|'grammar'|'flashcards';
type Language = 'en'|'es';
type Word = typeof raw.vocabulary[number] & {spanish?:string};
type Hanzi = {id:number;char:string;lesson:number;words:string[];meaningEnglish?:string;meaningSpanish?:string};
type Phrase = {id:string; lesson:number; hanzi:string; pinyin:string; translation:string; spanish:string; english:string; source:string};
const data = raw as { vocabulary: Word[]; sentences: typeof raw.sentences; grammar: typeof raw.grammar; grammarPhrases: Phrase[]; hanzi: Hanzi[] };
const extraLesson=19;
const extraHanziMeanings:Record<string,{en:string;es:string}>={"足":{en:"foot; sufficient",es:"pie; suficiente"},"累":{en:"tired; to accumulate",es:"cansado; acumular"},"床":{en:"bed",es:"cama"},"火":{en:"fire",es:"fuego"},"汉":{en:"Han Chinese; Chinese language",es:"chino han; idioma chino"},"苹":{en:"apple",es:"manzana"},"弟":{en:"younger brother",es:"hermano menor"},"读":{en:"to read; to study",es:"leer; estudiar"},"步":{en:"step; to walk",es:"paso; caminar"},"俩":{en:"two people",es:"dos personas"},"哥":{en:"older brother",es:"hermano mayor"},"教":{en:"to teach",es:"enseñar"}};
const extraHanzi:Hanzi[]=(()=>{const known=new Set(data.hanzi.map(item=>item.char));const studyText=[...data.vocabulary.flatMap(item=>[item.hanzi,item.example||'']),...data.sentences.map(item=>item.hanzi),...data.grammarPhrases.map(item=>item.hanzi),...data.grammar.flatMap(item=>item.examples.split(/\r?\n/).map(example=>example.replace(/^\d+\.\s*/,'')))].join('');return [...new Set([...studyText].filter(char=>/[\u3400-\u9fff]/.test(char)&&!known.has(char)))].map((char,index)=>({id:9000+index,char,lesson:extraLesson,words:data.vocabulary.filter(word=>word.hanzi.includes(char)).map(word=>word.hanzi),meaningEnglish:extraHanziMeanings[char]?.en,meaningSpanish:extraHanziMeanings[char]?.es}))})();
data.hanzi.push(...extraHanzi);
const modes: {id:Mode; label:string; es:string}[] = [
 {id:'hanzi',label:'Hanzi',es:'Caracteres'}, {id:'words',label:'Words',es:'Palabras'}, {id:'phrases',label:'Phrases',es:'Frases'}, {id:'grammar',label:'Grammar',es:'Gramática'}, {id:'flashcards',label:'Flashcards',es:'Tarjetas'},
];
const speak=(text:string, lang='zh-CN')=>{ if ('speechSynthesis' in window) { window.speechSynthesis.cancel(); const u=new SpeechSynthesisUtterance(text); u.lang=lang; u.rate=.82; window.speechSynthesis.speak(u); } };
const lessonTitle=(n:number)=>n===extraLesson?'Extra':`Lesson ${n}`;
const modeLabel=(mode:Mode,language:Language)=>({hanzi:language==='es'?'Caracteres':'Hanzi',words:language==='es'?'Palabras':'Words',phrases:language==='es'?'Frases':'Phrases',grammar:language==='es'?'Gramática':'Grammar',flashcards:language==='es'?'Tarjetas':'Flashcards'}[mode]);
const t=(language:Language,en:string,es:string)=>language==='es'?es:en;
const normalizeSearch=(value:string)=>value.normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase();
function useStored<T>(key:string, initial:T):[T,(v:T)=>void]{ const [value,setValue]=useState<T>(()=>{try{return JSON.parse(localStorage.getItem(key)||'null')??initial}catch{return initial}}); const save=(v:T)=>{setValue(v);localStorage.setItem(key,JSON.stringify(v))}; return [value,save]; }

export default function App(){
 const [mode,setMode]=useState<Mode>('hanzi'); const [language,setLanguage]=useStored<Language>('hsk3-language','en'); const [lesson,setLesson]=useState(1); const [lessonMenuOpen,setLessonMenuOpen]=useState(false); const [favoritesOnly,setFavoritesOnly]=useState(false); const [query,setQuery]=useState(''); const [favorites,setFavorites]=useStored<string[]>('hsk3-favorites',[]); const [studied,setStudied]=useStored<string[]>('hsk3-studied',[]); const [studyCounts,setStudyCounts]=useStored<Record<string,number>>('hsk3-study-counts',{}); const [flashResults,setFlashResults]=useStored<Record<string,{good:number;bad:number}>>('hsk3-flash-results',{}); const [flashIndex,setFlashIndex]=useState(0); const [flipped,setFlipped]=useState(false); const [flashMode,setFlashMode]=useState<'hanzi'|'words'|'phrases'|'grammar'|'mix'>('hanzi'); const [selectedWord,setSelectedWord]=useState<Word|null>(null); const [selectedHanzi,setSelectedHanzi]=useState<(typeof data.hanzi)[number]|null>(null); const [showTermsModal,setShowTermsModal]=useState(false);
 const lessons=[...Array.from({length:18},(_,i)=>i+1),extraLesson];
 const lessonWords=useMemo(()=>data.vocabulary.filter(v=>v.lesson===lesson),[lesson]);
 const q=normalizeSearch(query.trim());
 const pinyinQuery=pinyinSyllables.has(q);
 const wordScope=q?data.vocabulary:lessonWords;
 const words=wordScope.filter(v=>(!favoritesOnly || favorites.includes(v.id)) && (!q || normalizeSearch([v.hanzi,v.pinyin,v.english,v.example].join(' ')).includes(q)));
 const phraseMetadata=(english:string)=>{const match=english.match(/^(.*?)\s*\((.*?)\)$/);return {pinyin:match?.[1]||'',translation:match?.[2]||''}}; const grammarPhrases=data.grammarPhrases.map(phrase=>({...phrase,...phraseMetadata(phrase.english),pinyin:phrase.pinyin})); const splitPhraseParts=(value:string)=>value.split(/\s*\/\s*/).map(part=>part.trim()).filter(Boolean); const buildPhrases=(vocabulary:Word[],grammar:Phrase[]):Phrase[]=>[...vocabulary.filter(v=>v.example).flatMap(v=>{const combinedSentence=data.sentences.find(item=>item.hanzi===v.example);const parts=splitPhraseParts(v.example);const pinyinParts=combinedSentence?.pinyin?splitPhraseParts(combinedSentence.pinyin):[];const translations=combinedSentence?.english?splitPhraseParts(combinedSentence.english):[];const spanishTranslations=combinedSentence?.spanish?splitPhraseParts(combinedSentence.spanish):[];return parts.map((part,index)=>{const sentence=data.sentences.find(item=>item.hanzi===part);const metadata=grammarPhrases.find(phrase=>phrase.hanzi===part);return {id:parts.length>1?`${v.id}-${index+1}`:v.id,lesson:v.lesson,hanzi:part,pinyin:sentence?.pinyin||metadata?.pinyin||pinyinParts[index]||'',translation:sentence?.english||metadata?.translation||translations[index]||'',spanish:sentence?.spanish||metadata?.spanish||spanishTranslations[index]||'',english:sentence?.english||metadata?.translation||translations[index]||'',source:v.hanzi}})}),...grammar]; const allPhrases=buildPhrases(data.vocabulary,grammarPhrases); const phraseWordScope=q?data.vocabulary:lessonWords; const phrases: Phrase[]=buildPhrases(phraseWordScope,q?grammarPhrases:grammarPhrases.filter(p=>p.lesson===lesson)).filter(p=>!q || normalizeSearch([p.hanzi,p.pinyin,p.translation,p.spanish,p.source].join(' ')).includes(q));
 const grammar=data.grammar.filter(g=>(q||g.lesson===lesson) && (!favoritesOnly || favorites.includes(g.id)) && (!q || normalizeSearch([g.point,g.name,g.spanishName||'',g.formula,g.notes,g.spanishNotes||'',g.examples].join(' ')).includes(q)));
 const hanzi=data.hanzi.filter(h=>{if(!q&&h.lesson!==lesson)return false;if(!q)return true;const exactWords=data.vocabulary.filter(word=>word.hanzi===h.char);const relatedWords=data.vocabulary.filter(word=>[...word.hanzi].includes(h.char));const pronunciationMatch=relatedWords.some(word=>{const chars=[...word.hanzi];const syllables=splitPinyin(cleanPinyin(word.pinyin),chars.length);return chars.some((char,index)=>char===h.char&&Boolean(syllables[index])&&normalizeSearch(syllables[index]).startsWith(q))});const meaningMatch=!pinyinQuery&&(exactWords.some(word=>normalizeSearch([word.english,word.spanish||''].join(' ')).includes(q))||normalizeSearch([h.meaningEnglish||'',h.meaningSpanish||''].join(' ')).includes(q));return normalizeSearch(h.char).includes(q)||pronunciationMatch||meaningMatch});
 const flashcards=lessonWords.length?lessonWords:data.vocabulary.slice(0,20); const flashcardCount=flashMode==='hanzi'?hanzi.length:flashMode==='words'?words.length:flashMode==='phrases'?phrases.length:flashMode==='grammar'?grammar.length:hanzi.length+words.length+phrases.length+grammar.length; const card=flashcards[flashIndex%flashcards.length];
 const toggleFavorite=(id:string)=>setFavorites(favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id]);
 const clearFavorites=()=>setFavorites([]);
 const resetStudy=(ids:string|string[])=>{const resetIds=new Set(Array.isArray(ids)?ids:[ids]);setStudyCounts(Object.fromEntries(Object.entries(studyCounts).filter(([key])=>!resetIds.has(key))));setStudied(studied.filter(value=>!resetIds.has(value)))};
 const mark=(id:string)=>{setStudyCounts({...studyCounts,[id]:(studyCounts[id]||0)+1});if(!studied.includes(id))setStudied([...studied,id])};
 const recordFlashResult=(id:string,result:'good'|'bad')=>{const previous=flashResults[id]||{good:0,bad:0};setFlashResults({...flashResults,[id]:{...previous,[result]:previous[result]+1}});mark(id)};
 const resetFlashResults=()=>setFlashResults({});
 const pushRoute=(hash:string)=>window.history.pushState({},'',hash);
 const go=(m:Mode)=>{setFavoritesOnly(false);pushRoute(`#${m}-lesson-${lesson}`);setMode(m);setSelectedWord(null);setSelectedHanzi(null);setFlipped(false)};
 const openHanzi=(item:typeof data.hanzi[number])=>{pushRoute(`#hanzi-${item.id}`);setMode('hanzi');setSelectedHanzi(item);setSelectedWord(null)};
 const openWord=(word:Word)=>{pushRoute(`#word-${word.id}`);setMode('words');setSelectedWord(word);setSelectedHanzi(null)};
 const openLesson=(m:Mode,n:number)=>{pushRoute(`#${m}-lesson-${n}`);setLesson(n);setMode(m);setSelectedWord(null);setSelectedHanzi(null);setFlashIndex(0);setFlipped(false)};
 useEffect(()=>{const sync=()=>{const hash=window.location.hash;if(hash==='#favorites'){setFavoritesOnly(true);setMode('words');setSelectedWord(null);setSelectedHanzi(null);return}setFavoritesOnly(false);const hanziMatch=hash.match(/^#hanzi-(\d+)$/);if(hanziMatch){const item=data.hanzi.find(h=>String(h.id)===hanziMatch[1]);if(item){setMode('hanzi');setSelectedHanzi(item);setSelectedWord(null)}return}const wordMatch=hash.match(/^#word-(.+)$/);if(wordMatch){const item=data.vocabulary.find(word=>word.id===wordMatch[1]);if(item){setMode('words');setSelectedWord(item);setSelectedHanzi(null)}return}const routeMatch=hash.match(/^#(hanzi|words|phrases|grammar|flashcards)-lesson-(\d+)$/);if(routeMatch){setMode(routeMatch[1] as Mode);setLesson(Number(routeMatch[2]));setSelectedWord(null);setSelectedHanzi(null);return}setSelectedWord(null);setSelectedHanzi(null)};window.addEventListener('popstate',sync);if(!window.location.hash)window.history.replaceState({},'',`#hanzi-lesson-${lesson}`);sync();return()=>window.removeEventListener('popstate',sync)},[]);
 return <div className="app-shell">
  <header className="topbar"><div className="brand"><div className="brand-mark">新</div><div><strong>New HSK 3</strong><span>{t(language,'Learner','Aprendiz')}</span></div></div><div className="header-meta"><div className="language-toggle" role="group" aria-label={t(language,'Interface language','Idioma de la interfaz')}><Languages size={15}/><button className={language==='en'?'active':''} onClick={()=>setLanguage('en')} aria-pressed={language==='en'}>EN</button><button className={language==='es'?'active':''} onClick={()=>setLanguage('es')} aria-pressed={language==='es'}>ES</button></div></div></header>
  <main className="workspace">
   <section className="controls"><div className="lesson-picker"><button className="lesson-trigger" type="button" aria-haspopup="listbox" aria-expanded={lessonMenuOpen} onClick={()=>setLessonMenuOpen(value=>!value)}>{language==='es'?`Lección ${lesson}`:lessonTitle(lesson)}<ChevronDown size={17}/></button>{lessonMenuOpen&&<div className="lesson-menu" role="listbox" aria-label={t(language,'Lessons','Lecciones')}>{lessons.map(n=><button key={n} type="button" role="option" aria-selected={lesson===n} className={lesson===n?'selected':''} onClick={()=>{openLesson(mode,n);setLessonMenuOpen(false)}}>{language==='es'?`Lección ${n}`:lessonTitle(n)}</button>)}</div>}</div><div className="search-wrap"><Search size={18}/><input aria-label={t(language,'Search','Buscar')} placeholder={t(language,'Search hanzi, pinyin, English…','Buscar hanzi, pinyin o español…')} value={query} onChange={e=>setQuery(e.target.value)}/>{query&&<button className="icon-btn" onClick={()=>setQuery('')} aria-label={t(language,'Clear search','Borrar búsqueda')}><X size={16}/></button>}</div></section>
   <nav className="mode-tabs" aria-label={t(language,'Study modes','Modos de estudio')}>{modes.map(m=><button key={m.id} className={mode===m.id&&!favoritesOnly?'active':''} onClick={()=>go(m.id)}>{modeLabel(m.id,language)}</button>)}<button className={'favorites-tab '+(favoritesOnly?'active':'')} onClick={()=>{setFavoritesOnly(true);pushRoute('#favorites');setMode('words');setSelectedWord(null);setSelectedHanzi(null)}}><Heart size={15} fill={favoritesOnly?'currentColor':'none'}/> {t(language,'Favorites','Favoritos')} <small>{favorites.length}</small></button></nav>
   {!favoritesOnly&&!selectedHanzi&&!selectedWord&&<div className="content-heading"><div><h2>{modeLabel(mode,language)}</h2><span className="section-context">{lesson===extraLesson?t(language,'Extra active','Extra activa'):language==='es'?`Lección ${lesson} activa`:`Lesson ${lesson} active`}</span></div><span className="result-count">{mode==='hanzi'?hanzi.length:mode==='words'?words.length:mode==='phrases'?phrases.length:mode==='grammar'?grammar.length:flashcardCount} {t(language,'items','elementos')}</span></div>}
   {favoritesOnly&&<FavoritesView favorites={favorites} hanzi={data.hanzi.filter(item=>favorites.includes(`hanzi-${item.id}`))} words={data.vocabulary.filter(item=>favorites.includes(item.id))} phrases={allPhrases.filter(item=>favorites.includes(`phrase-${item.id}`))} grammar={data.grammar.filter(item=>favorites.includes(item.id))} onSelect={word=>{setFavoritesOnly(false);openWord(word)}} onHanzi={item=>{setFavoritesOnly(false);openHanzi(item)}} onLesson={openLesson} mark={mark} studyCounts={studyCounts} resetStudy={resetStudy} toggleFavorite={toggleFavorite} resetFavorites={clearFavorites} language={language}/>}
   {!favoritesOnly&&mode==='hanzi'&&<HanziView items={hanzi} onSelect={h=>{mark(`h-${h.id}`);openHanzi(h)}} selected={selectedHanzi} onBack={()=>window.history.back()} onWord={openWord} onLesson={openLesson} favorites={favorites} toggleFavorite={toggleFavorite} studyCounts={studyCounts} resetStudy={()=>resetStudy(hanzi.map(item=>`h-${item.id}`))} language={language}/>}
   {!favoritesOnly&&mode==='words'&&!selectedWord&&<WordsView items={words} favorites={favorites} toggleFavorite={toggleFavorite} mark={mark} studyCounts={studyCounts} resetStudy={()=>resetStudy(words.map(item=>item.id))} onSelect={openWord} favoritesOnly={favoritesOnly} language={language}/>}
   {!favoritesOnly&&mode==='phrases'&&<PhrasesView items={phrases} onSelect={openWord} onHanzi={openHanzi} favorites={favorites} toggleFavorite={toggleFavorite} language={language}/>}
   {!favoritesOnly&&mode==='grammar'&&<GrammarView items={grammar} onWord={openWord} onHanzi={openHanzi} favorites={favorites} toggleFavorite={toggleFavorite} language={language}/>}
   {!favoritesOnly&&mode==='flashcards'&&<FlashcardsViewV3 lesson={lesson} language={language} mode={flashMode} setMode={setFlashMode} index={flashIndex} setIndex={setFlashIndex} flipped={flipped} setFlipped={setFlipped} results={flashResults} recordResult={recordFlashResult} resetResults={resetFlashResults} />}
   {selectedWord&&<WordDetail word={selectedWord} close={()=>window.history.back()} favorite={favorites.includes(selectedWord.id)} toggle={()=>toggleFavorite(selectedWord.id)} favorites={favorites} toggleFavorite={toggleFavorite} onLesson={openLesson} onWord={openWord} onHanzi={openHanzi} language={language} />}
  </main><footer><div className="footer-meta"><span>© 2026 New-HSK-3-Learner</span><span aria-hidden="true">·</span><span className="footer-license">MIT License</span><span aria-hidden="true">·</span><a href="https://github.com/Connum/hanzivg" target="_blank" rel="noopener noreferrer">HanziVG (CC BY-SA 3.0)</a></div><button className="footer-terms" onClick={()=>setShowTermsModal(true)}>{t(language,'Terms, Privacy and Licenses','Términos, Privacidad y Licencias')}</button></footer><TermsPrivacyModal language={language} open={showTermsModal} onClose={()=>setShowTermsModal(false)}/>
 </div>
}
function TermsPrivacyModal({language,open,onClose}:{language:Language;open:boolean;onClose:()=>void}){if(!open)return null;return <div className="modal-backdrop" onClick={onClose}><section className="terms-modal" role="dialog" aria-modal="true" aria-labelledby="terms-title" onClick={event=>event.stopPropagation()}><div className="terms-modal-header"><div><ShieldCheck size={19}/><h2 id="terms-title">{t(language,'Terms, Privacy and Licenses','Términos, Privacidad y Licencias')}</h2></div><button className="modal-close" onClick={onClose} aria-label={t(language,'Close','Cerrar')}><X size={18}/></button></div><div className="terms-modal-body"><section><h3><ShieldCheck size={15}/>{t(language,'Privacy','Privacidad')}</h3><p>{t(language,'This is a static application. It has no accounts, tracking cookies, external analytics, or server-side profile. Study progress, favorites, and language preferences are stored only in your browser localStorage.','Esta es una aplicación estática. No tiene cuentas, cookies de seguimiento, analítica externa ni perfiles en servidores. El progreso, los favoritos y el idioma se guardan únicamente en el localStorage de tu navegador.')}</p></section><section><h3><FileText size={15}/>{t(language,'Terms of use','Términos de uso')}</h3><p>{t(language,'This free tool is provided for educational use, as-is and without guarantees. Course content and translations are presented to support independent study.','Esta herramienta gratuita se ofrece con fines educativos, tal cual y sin garantías. El contenido y las traducciones se presentan para apoyar el estudio independiente.')}</p></section><section><h3><Code2 size={15}/>{t(language,'Software and resources','Software y recursos')}</h3><p>{t(language,'The application code is released under the MIT License. Stroke order assets are provided by HanziVG by Connum and contributors, and Make Me a Hanzi fallback data by Skishore, under their respective CC BY-SA licenses.','El código de la aplicación se publica bajo la licencia MIT. Los trazos proceden de HanziVG, de Connum y sus colaboradores, y de los datos alternativos de Make Me a Hanzi, de Skishore, bajo sus respectivas licencias CC BY-SA.')}</p><p><a href="https://github.com/Connum/hanzivg" target="_blank" rel="noopener noreferrer">github.com/Connum/hanzivg</a> · <a href="https://github.com/skishore/makemeahanzi" target="_blank" rel="noopener noreferrer">Make Me a Hanzi</a> · <a href="./LICENSE">MIT License</a></p></section></div></section></div>}
function Audio({text,className=''}:{text:string;className?:string}){return <button className={`audio-btn ${className}`} onClick={()=>speak(text)} aria-label={`Play ${text}`}><Volume2 size={16}/></button>}
function Favorite({active,onClick,className=''}:{active:boolean;onClick:(event:MouseEvent<HTMLButtonElement>)=>void;className?:string}){return <button className={`favorite ${className} ${active?'on':''}`} onClick={onClick} aria-label="Favorite"><Heart size={17} fill={active?'currentColor':'none'}/></button>}
type StrokePath = {d:string}; type StrokeNumber = {text:string;transform:string};
type StrokeData = {paths:StrokePath[];numbers:StrokeNumber[];scale?:number;transform?:string;filled?:boolean};
async function loadStrokeData(char:string):Promise<StrokeData|null>{const hex=char.codePointAt(0)?.toString(16).padStart(5,'0')||'';for(const base of ['https://raw.githubusercontent.com/Connum/hanzivg/master/hanzi/','https://raw.githubusercontent.com/Connum/hanzivg/master/kanji/']){try{const response=await fetch(`${base}${hex}.svg`);if(!response.ok)continue;const doc=new DOMParser().parseFromString(await response.text(),'image/svg+xml');const paths=Array.from(doc.querySelectorAll('path[id*="-s"]')).map(path=>({d:path.getAttribute('d')||''})).filter(path=>path.d);const numbers=Array.from(doc.querySelectorAll('g[id*="StrokeNumbers"] text')).map(text=>({text:text.textContent?.trim()||'',transform:text.getAttribute('transform')||''})).filter(item=>item.text);if(paths.length)return {paths,numbers}}catch{}}return loadFallbackStrokeData(char)}
let fallbackStrokeData:Promise<Map<string,{strokes:string[];medians:number[][][]}>>|null=null;
async function loadFallbackStrokeData(char:string):Promise<StrokeData|null>{
 if(!fallbackStrokeData)fallbackStrokeData=fetch('https://raw.githubusercontent.com/skishore/makemeahanzi/master/graphics.txt').then(async response=>{
  if(!response.ok)throw new Error(`Stroke fallback request failed: ${response.status}`);
  const map=new Map<string,{strokes:string[];medians:number[][][]}>();
  const text=await response.text();
  text.split(/\r?\n/).forEach(line=>{if(!line)return;try{const record=JSON.parse(line) as {character?:string;strokes?:string[];medians?:number[][][]};if(record.character&&record.strokes?.length)map.set(record.character,{strokes:record.strokes,medians:record.medians||[]})}catch{}});
  return map;
 }).catch(error=>{fallbackStrokeData=null;throw error});
 const record=(await fallbackStrokeData).get(char);
 if(!record?.strokes.length)return null;
 const points=record.medians.flat();
 const minX=Math.min(...points.map(point=>point[0])),maxX=Math.max(...points.map(point=>point[0]));
 const minY=Math.min(...points.map(point=>point[1])),maxY=Math.max(...points.map(point=>point[1]));
 const scale=93/Math.max(maxX-minX,maxY-minY);
 const offsetX=(109-(maxX-minX)*scale)/2-minX*scale;
 const offsetY=(109-(maxY-minY)*scale)/2+maxY*scale;
 const transform=`translate(${offsetX} ${offsetY}) scale(${scale} ${-scale})`;
 const numbers=record.medians.map((median,index)=>{const point=median[0];return point?{text:String(index+1),transform:`translate(${offsetX+point[0]*scale} ${offsetY-point[1]*scale})`}:null}).filter((number):number is StrokeNumber=>number!==null);
 return {paths:record.strokes.map(d=>({d})),numbers,transform,filled:true};
}
